def minPath(grid, k):
    n = len(grid)
    if k == 1:
        return [min(min(row) for row in grid)]

    # 记录每个值的位置
    pos = {}
    for i in range(n):
        for j in range(n):
            pos[grid[i][j]] = (i, j)

    # 从值1开始
    start = pos[1]
    # 当前最优路径
    best = None

    # 使用BFS按字典序扩展
    from collections import deque
    # 队列元素: (路径, 当前位置)
    q = deque()
    q.append(([1], start))

    while q:
        path, (x, y) = q.popleft()
        if len(path) == k:
            if best is None or path < best:
                best = path
            continue

        # 获取邻居值并排序
        neighbors = []
        for dx, dy in [(-1,0),(1,0),(0,-1),(0,1)]:
            nx, ny = x+dx, y+dy
            if 0 <= nx < n and 0 <= ny < n:
                neighbors.append(grid[nx][ny])
        neighbors.sort()

        for val in neighbors:
            nx, ny = pos[val]
            new_path = path + [val]
            # 剪枝：如果当前路径已经比best差，跳过
            if best is not None:
                # 比较前缀
                prefix_len = len(new_path)
                if prefix_len > len(best):
                    prefix_len = len(best)
                if new_path[:prefix_len] > best[:prefix_len]:
                    continue
            q.append((new_path, (nx, ny)))

    return best
